(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["non"] = {"ui":{"skip":"Hlaupa til efnis","back":"← Aftr til AI-gile","lang.button":"Tunga: {name}","lang.dialog":"Veldu tungu","lang.search":"Leita at tungum","lang.none":"Engin tunga samsvarar","lang.notYet":"{name} er eigi þýdd enn","theme.aria":"Skipta milli ljóss ok dökks yfirbragðs","theme.toLight":"Skipta til ljóss yfirbragðs","theme.toDark":"Skipta til dökks yfirbragðs","words.underline":"Strika undir þessi orð á síðunni","words.underlineHelp":"Hald músinni yfir orði með deplóttri línu, eða drep á þat, til at sjá hvat þat merkir.","index.title":"AI-gile: gervigreindarsveit þín, á einu borði","index.description":"AI-gile er kanban-borð fyrir gervigreindar-kóðasveitir. Þær vinna meðan þú sefr; þú færð einn stuttan haug af hlutum at ákveða, prófa ok samþykkja.","hero.logoAlt":"Tákn AI-gile-borðsins","hero.h1.html":"Gervigreindarsveit þín, á einu&nbsp;borði.","hero.alpha":"🐣 Lokat for-alfa","hero.alphaTitle":"Snemma ok ólokit: þökk fyrir at reyna!","hero.lede":"Þær smíða meðan þú sefr. Þú vaknar við einn stuttan haug: nokkrar spurningar, nokkra hluti at prófa, einn fjólubláan tígul eða tvá. Smelltu, samþykktu, ok aftr til kaffis þíns.","dl.windows":"Windows-forrit","dl.browser":"Rek þat í vafra þínum","dl.soon":"Kemr brátt","dl.notify":"🔔 Seg mér, þá er þat opnast","dl.notifySmall":"Alfa eða beta","hero.secondary":"Agile, en sveitin þarf aldri kaffi á stand-up. (Þær halda stand-up þó.)","pitch.h2":"AI-gile í svá mörgum orðum sem þú vilt","pitch.lede":"Veldu lengd, frá einu orði til 144. Hver lengd er sín eigin lýsing, rituð fyrir þá stærð. Dragðu sleðann eða notaðu örvalyklana.","pitch.rangeLabel":"Lengd í orðum","pitch.dice":"🎲 önnur gerð","pitch.words.one":"{n} orð","pitch.words.other":"{n} orð","pitch.letters.one":"{n} stafr","pitch.letters.other":"{n} stafir","pitch.chars.one":"{n} tákn","pitch.chars.other":"{n} tákn","count.line.html.one":"{n} spjald á borðinu nú","count.line.html.other":"{n} spjöld á borðinu nú","features.aria":"Hvat þat gerir","f.pile.h":"Einn haugr handa þér","f.pile.html":"<b>Til þín</b> geymir allt sem bíðr þín, í öllum verkum: spurningar, hluti at prófa, störf er aðeins maðr má vinna. Röð þín segir hvat er næst ok hve lengi þat tekr.","f.sleep.h":"Sveitir er vinna meðan þú sefr","f.sleep.p":"Hvert verk hefr leiðtoga ok sveit gervigreindar-erindreka. Gerðu ummæli á spjald ok sveitin vaknar, vinnr verkit ok skilar því aftr með skrefum er þreyttr maðr má fylgja.","f.tester.h":"Gervigreindarprófari lítr fyrst á","f.tester.p":"Áðr en nokkut kemr til þín, fylgir prófari skrefunum í eftirmynd forritsins ok sýnir hvat hann sá, með skjámynd. Flettu gegnum þau er stóðust ok samþykktu með einum smelli.","f.proof.h":"Sannanir, eigi heit","f.proof.p":"Hver afhending sýnir hvat breyttist: skrárnar, muninn, skjámyndirnar. Þú þarft eigi at opna hvert forrit til at sjá hvárt því sé lokit.","f.chat.h":"Ræð við leiðtoga þína","f.chat.p":"Rönd í Discord-stíl: eitt tákn fyrir hvert verk, fjólubláir tíglar fyrir þat er þarfnast þín. Send leiðtoga hugmynd; hann gerir hana at spjöldum ok áætlun, með ✅ Go-hnappi.","f.tidy.h":"Heldr sjálfr reglu","f.tidy.p":"Skyld spjöld renna saman, ruglingsleg heiti eru löguð, ok tákna-athugun heldr kóðanum mjóum. Færra at skipta milli, minna at hugsa um.","f.private.h":"Þitt, á þinni eigin tölvu","f.private.li1":"Borðit gengr á þinni eigin vél ok svarar aðeins þér.","f.private.li2":"Einkaskilaboð milli manna eru dulrituð frá enda til enda.","f.private.li3":"Engir reikningar, engir eltarar, engar kökur.","f.lang.h":"Á þinni tungu","f.lang.p":"Yfir 120 tungur, frá norrœnu, velsku ok japönsku til sjóræningja, Yoda ok klingonsku, með skjótum rofa aftr til ensku fyrir orð þróunarmanna.","tl.aria":"Tímalína frá fyrsta samtali til vegvísis","tl.h2":"Frá fyrsta spjalli til þess er næst kemr","tl.lede":"Sannar dagsetningar ok stundir, á þínu tímabelti. Eftir í dag er þat áætlun, án heitinna daga.","tl.today":"Í dag","tl.planned":"áætlat","tl.cards.one":"{n} spjald","tl.cards.other":"{n} spjöld","join.h2":"Gakk í lið","join.lede":"AI-gile er smíðat af einum litlum manni ok mörgum þolinmóðum erindrekum. Enn er þat einkamál, lokat alfa með vinum. Viltu reyna þá er þat opnast?","join.btn":"Skrá áhuga","join.small":"Vér sendum þér póst, ekki meira","footer.tag":"AI-gile. Engir eltarar, engar kökur, ekkert stand-up-kaffi.","footer.licence":"Starfsleyfi","footer.status":"Staða","footer.privacy":"Hvat vér geymum","form.sending":"Sendi…","form.failed":"Þat tókst eigi: reyn aftr síðar.","form.offline":"Náði eigi til AI-gile: reyn aftr síðar.","form.keep":"Vér notum þetta einungis til at svara þér, ok eyðum því síðan. Engir eltarar, engar kökur.","form.keepLink":"Hvat vér geymum","interest.title":"AI-gile: seg mér þá er alfa opnast","interest.description":"Skildu eftir netfang þitt til at heyra þá er lokat alfa eða beta AI-gile opnast.","interest.h1":"🔔 Seg mér, þá er þat opnast","interest.lede":"AI-gile er í lokuðu for-alfa. Skildu eftir netfang þitt, ok vér skrifum einu sinni, þá er rúm er fyrir þik.","interest.email":"Netfang þitt","interest.which":"Hvert próf?","interest.alpha":"Lokat alfa: snemma, hrátt, margar breytingar","interest.beta":"Beta: stöðugra, síðar","interest.both":"Hvárt sem er, hvat sem fyrst kemr","interest.submit":"Settu mik á listann","interest.thanks":"Þökk! Þú ert á listanum.","licence.title":"AI-gile: starfsleyfi","licence.description":"Notar þú AI-gile í fyrirtæki þínu? Sæktu um ókeypis starfsleyfi.","licence.h1":"📜 Starfsleyfi","licence.lede":"Notar þú AI-gile í vinnu? Seg oss hverr þú ert ok hvat þú gerir. Ef þat gerir nokkut gott, er leyfit ókeypis.","licence.company":"Fyrirtæki","licence.website":"Vefsíða","licence.what":"Hvat þú gerir","licence.how":"Hversu þat hjálpar heiminum","licence.email":"Netfang","licence.submit":"Sækja um","licence.thanks":"Þökk! Vér svörum með pósti.","status.title":"Staða AI-gile","status.h1":"Staða AI-gile","status.quiet":"Allt er kyrrt","status.intro":"Starfar AI-gile nú? Þessi síða athugar vefinn, borðadeilingu, símtöl ok niðrhalit á 5 mínútna fresti.","status.up":"Starfar (svaraði á {ms} ms)","status.slow":"Svaraði eigi síðustu athugun, reyni aftr","status.down":"Niðri: svaraði eigi tveim síðustu athugunum","status.svc.web":"Vefr","status.svc.web.offers":"Þessi vefr: hvat AI-gile er, ok áhugaformit","status.svc.boards":"Borðadeiling","status.svc.boards.offers":"Opin borð, skilaboð milli vina ok boð","status.svc.calls":"Símtöl","status.svc.calls.offers":"Rödd, myndband ok skjádeiling í AI-gile","status.svc.download":"Niðrhal","status.svc.download.offers":"Windows-uppsetningin ok boðstenglar","status.checking":"Athuga…","status.offline":"Næ eigi til stöðuþjónustunnar nú (reyni aftr)","status.updated":"nýjat {ago}","status.justNow":"rétt nú","status.min":"{n}m síðan","status.hours":"{n}t síðan","status.days":"{n}d síðan","privacy.title":"AI-gile: hvat vér geymum","privacy.h1":"Hvat vér geymum","privacy.lede":"Í stuttu máli: aðeins þat er þú sendir oss, ok eigi lengi.","privacy.only":"Aðeins þat er þú sendir oss: þat er þú ritar í form, svá sem netfang þitt. Ekkert annat um þik.","privacy.sealed":"Þat er innsiglat svá at þjónn várr fái eigi lesit þat: í vafra þínum áðr en þat ferr (í eldri vafra, þegar er þat kemr). Aðeins várt eigit borð má opna þat.","privacy.server":"Því er eytt af þjóninum jafnskjótt sem þat nær borði váru. Allt er þar liggr enn eftir 30 daga er eytt engu at síðr.","privacy.board":"Vér geymum þat á borði váru aðeins unz vér höfum svarat þér, ok eyðum því þar síðan.","privacy.none":"Engir eltarar, engar kökur, engar mælingar.","privacy.local":"Mál þitt ok val milli ljóss ok dökks haldast í þínum eigin vafra. Þau eru aldri send oss.","privacy.ask":"Viltu at því sé eytt fyrr? Svara bréfi váru ok seg svá.","live.h2":"Sjá þat byggjask, lífs","live.caption":"Hvert spjald er hulit: þú sér líking verksins, eigi orðin.","live.watching.one":"lífs: {n} sér","live.watching.other":"lífs: {n} sjá","live.last.now":"Síðasta spjald var fært rétt nú","live.last.min.one":"Síðasta spjald var fært fyrir {n} mín.","live.last.min.other":"Síðasta spjald var fært fyrir {n} mín.","live.last.hour.one":"Síðasta spjald var fært fyrir {n} stund","live.last.hour.other":"Síðasta spjald var fært fyrir {n} stundum","live.last.day.one":"Síðasta spjald var fært fyrir {n} degi","live.last.day.other":"Síðasta spjald var fært fyrir {n} dögum","live.offline":"Lífs taflan hvílisk um stund. Kom aptr brátt.","live.cols":"Backlog|Til gerðar|Í verki|Sveitin lítr á|Til þín at testa|Til sveitar|Lokit"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Erindrekar.","Falit."]},{"n":2,"texts":["Erindrekar, skipaðir.","Hugmyndir, smíðaðar.","Erindrekar vinna."]},{"n":3,"texts":["Kanban fyrir erindreka.","Hugmyndir verða eiginleikar.","Ókeypis, heima, prófat."]},{"n":5,"texts":["Borð þar er erindrekar smíða.","Þú ritar spjöld. Erindrekar smíða.","Ókeypis, heima, prófat, lítit skrýtit."]},{"n":8,"texts":["Ókeypis kanban-borð þar er gervigreindar-erindrekar vinna öll verkin.","Rit eina hugmynd. Erindrekar smíða hana. Þú samþykkir.","Agile fyrir einn mann ok marga þolinmóða erindreka."]},{"n":13,"texts":["Kanban-borð á tölvu þinni þar er gervigreindar-erindrekar taka spjöldin upp ok vinna þau.","Rit hugmynd. Sveit erindreka smíðar hana. Síðan lítr prófari á hana fyrir þik.","Ókeypis, engir reikningar né eltarar: borð, nokkrir erindrekar, ok þú ræðr öllu."]},{"n":21,"texts":["AI-gile er kanban-borð til at vinna með gervigreindar-kóðaerindrekum. Þeir taka spjöldin upp, hvert af öðru; þú prófar þau ok samþykkir.","Hvert verk fær leiðtoga ok sveit gervigreindar-erindreka. Gerðu ummæli á hvert spjald, ok þá tekr sveitin til starfa.","Ókeypis einkaborð til verka, er gengr á þinni eigin tölvu. Verkamennirnir eru erindrekar. Sá er segir já, ert þú."]},{"n":34,"texts":["Þú leggr hugmyndir á borð. Sveit gervigreindar-erindreka gerir þær at starfandi eiginleikum, prófar þá ok skilar þeim aftr með skrefum til at reyna. Ekkert telst lokit fyrr en þú segir svá.","AI-gile er heimagert kanban-borð er Rich smíðaði með mikilli hjálp erindreka þeirra er þat nú stýrir. Þat er ókeypis, gengr á tölvu þinni ok er deilt með vinum, eigi selt.","Hugsaðu þér venjulegt kanban-borð, með dálkum frá Backlog til Lokit, nema at spjöldin eru tekin af gervigreindar-erindrekum. Þeir segja frá framvindu, spyrja þá er þeir sitja fastir, ok bíða ávallt eftir þumli þínum upp."]},{"n":55,"texts":["AI-gile er kanban-borð þar er sveitin er gerð af gervigreindar-erindrekum. Hvert verk hefr leiðtoga er áætlar verkit ok hjálparmenn er smíða þat. Þá er eiginleiki er búinn, reynir gervigreindar-prófari hann ok tekr skjámynd, ok þá lendir hann á hauginum þínum. Samþykktu hann, eða gerðu ummæli, ok þeir vinna hann upp aftr.","Þat hófst sem leið eins manns til at halda utan um margar kóðalotur með gervigreind í senn, ok óx at réttu borði. Þat gengr á vél þinni, krefst engra reikninga ok hefr enga eltara. Þat er ókeypis fyrir vini ok forvitna. Þat er ok ólokit, svá búst við hrjúfum brúnum ok einni óvæntri uppákomu.","Hér er heiðarlega útgáfan. Þú verðr enn at eiga hugmyndirnar, ok þú verðr enn at líta á árangrinn. Þat er AI-gile gerir, er allt þar í milli: þat heldr spjöldunum í röð, vekr réttan erindreka þá er þú gerir ummæli, sýnir nákvæmlega hvat breyttist, ok safnar öllu í einn stuttan haug handa þér."]},{"n":89,"texts":["AI-gile er ókeypis kanban-borð er þú rekr á þinni eigin tölvu. Í stað manna hefr hvert verk sveit gervigreindar-erindreka: leiðtoga er gerir hugmyndir þínar at spjöldum ok áætlun, ok hjálparmenn er taka spjöldin í forgangsröð. Þá er eitthvat er smíðat, fylgir gervigreindar-prófari prófunarskrefunum ok sýnir þér hvat hann sá. Síðan bíðr þat í einum haug er heitir Til þín. Þú samþykkir þat, eða þú gerir ummæli ok sveitin reynir aftr. Ekkert kemst nokkurn tíma í Lokit án þín.","Nokkrir eiginleikar er þú væntir kannski eigi. Næturvörðr heldr Til gerðar-dálkinum fullum meðan þú sefr ok velr spjöld er þurfa eigi svar frá þér. Teljari sýnir hversu mikit erindrekarnir hafa notat í dag ok þessa viku, ok Engin tákn-hátr segir þeim at hætta at eyða. Þú mátt senda vinum skilaboð, ok einkaskilaboð eru dulrituð frá enda til enda. Borðit talar um 120 tungur, þar á meðal norrœnu, sjóræningja ok klingonsku. Ekkert af þessu kostar eyri, ok engi reynir at selja þér þat heldr.","AI-gile er lítit, persónulegt verk, eigi fyrirtæki. Rich vildi gæta margra gervigreindar-kóðaverka án þess at opna hvert forrit til at líta á þau, svá hann ok erindrekarnir smíðuðu borð til þess, ok notuðu síðan borðit til at smíða afganginn af sér sjálfu. Þat er í lokuðu for-alfa, sem merkir at þat virkar, mestanpart, fyrir fáeina vini. Hér er engin verðsíða, ekkert fréttabréf ok engin vaxtaráætlun. Ef þetta hljómar gagnlegt, mátt þú biðja um at reyna þat þá er þat opnast örlítit meira."]},{"n":144,"texts":["AI-gile er kanban-borð fyrir einn mann ok marga gervigreindar-erindreka. Þat gengr á þinni eigin tölvu ok er alveg ókeypis. Þú bætir við verkum, ok hvert verk fær leiðtoga ok litla sveit. Þú ræðr við leiðtogann, líkt ok á Discord, ok lýsir hugmynd; leiðtoginn gerir hana at spjöldum ok áætlun, ok bíðr þess at þú ýtir á Go. Sveitin vinnr sig gegnum spjöldin í forgangsröð, með einföldu skipanalínutóli gerðu fyrir mállíkön. Áðr en nokkut kemr aftr til þín, fylgir gervigreindar-prófari skrefunum í eftirmynd forritsins ok festir við skjámynd. Lokit verk lendir á hauginum þínum með breyttum skrám ok muninum. Þú samþykkir þat, eða þú skilr eftir ummæli, ok sveitin vaknar ok reynir aftr. Aðeins þú mátt færa spjald til Lokit.","Dagr með AI-gile, í grófum dráttum. At kveldi skilr þú eftir nokkur ummæli: þessi hnappr er á röngum stað, sá listi ætti at vera raðaðr, gætum vér fengit dökkan hátt. Þú ferr at sofa. Erindrekarnir lesa ummælin, gera breytingarnar, prófa þær ok skila þeim aftr til þín. Ef Til gerðar tæmist, fyllir næturvörðrinn þat úr backlog með spjöldum er þurfa ekkert svar frá þér. At morgni er þar einn stuttr haugr: nokkrar spurningar ok fáeinir hlutir at reyna, hver með skrefum er syfjaðr maðr má fylgja ok skjámynd af því at þat virkar. Þú smellir þig gegnum, samþykkir góðu spjöldin ok sendir hin aftr. Teljari sýnir hvat allt þetta notaði, ok Engin tákn-hátr er til fyrir magrar vikur. Síðan etr þú morgunverð, er erindrekarnir fá enn eigi hjálpat með.","Fyrst, hvat AI-gile er eigi. Þat er eigi sprotafyrirtæki, þat er eigi til sölu, ok engi safnar gögnum þínum. Þat er ókeypis borð er gengr á tölvu þinni, án reikninga, eltara eða kaka. Hvat þat er: einn snyrtiligr staðr til at sjá öll gervigreindar-kóðaverk þín senn, með sveit erindreka er vinnr spjöldin ok þik er tekr ákvarðanirnar. Þat steypir skyldum spjöldum saman, lagar ruglingsleg heiti ok fylgist með hversu mjór kóðinn helzt. Þat talar um 120 tungur, frá norrœnu til sjóræningja ok klingonsku. Vinir mega senda hverr öðrum skilaboð, einkaliga ok dulrituð. Þat var smíðat af Rich ok mörgum þolinmóðum erindrekum, er mestanpart notuðu þat sjálfir. Þat er í lokuðu for-alfa, svá þat er hrjúft sums staðar. Ef þat hljómar skemmtiligt, bið vel, ok kannski kemst þú snemma inn."]}],"quips":{"1":"Eitt orð. Djarft. Kannski of djarft.","3":"Þrjú orð. Þegar heiðarlegra en flestar vörusíður.","8":"Átta orð. Enn styttra en stand-up.","21":"Lengdirnar eru annars story points. Auðvitað eru þær þat.","55":"Fimmtíu ok fimm orð. Tvö spjöld lukust meðan þú last þetta.","144":"Þat var hit langa. Ekkert 233 er til. Erindrekarnir eru farnir at sofa."}},"timeline":{"first-idea.name":"Hin fyrsta hugmynd","first-idea.line":"Hit allra fyrsta samtal, áðr en nokkur kóði var til.","first-board.name":"Hit fyrsta borð","first-board.line":"Borð er heldr utan um sína eigin smíð: spjöld, dálka, draga ok sleppa, verk.","team-roles.name":"Sveit ok hlutverk","team-roles.line":"Erindrekasnið, sveitarsnið, rými ok hverr gerir hvat.","install.name":"Uppsetning ok útgáfur","install.line":"Zip-skrá er vinr má setja upp, sjálfnýjun, rásir ok afturhvarf.","usage-saver.name":"Notkunarsparnaðr","usage-saver.line":"Mæla hvat keyrslur kosta, halda kóðanum mjóum, spara mörk þín.","friends.name":"Vinir ok deiling","friends.line":"Einkaskilaboð, dulrituð miðlun, boð, hlutverk ok sameiginleg verk.","languages.name":"Tungur","languages.line":"Hver skjátexti í tungumálsskrá, með hollenzku ok flæmsku fyrst.","ai-tester.name":"Gervigreindarprófari","ai-tester.line":"Prófari lítr á hverja afhending fyrst ok sýnir hvat hann sá.","website.name":"Vefsíðan","website.line":"aigile.lol, forsmekkrinn ok þessi tímalína.","streaming.name":"Spjall ok streymi","streaming.line":"Discord, Twitch, OBS, streymishátr, GIF ok tjáknmyndir.","no-ai.name":"Útgáfa án gervigreindar","no-ai.line":"Borð fyrir þá er kóða án gervigreindar, ok opinber borð.","night-watch.name":"Næturvarðhald","night-watch.line":"Vörðr ok Scrum-meistari halda sveitunum við efnit meðan þú sefr.","p-more.name":"Allt annat","p-more.line":"Minni hugmyndir er enn bíða síns tíma.","p-android.name":"Sími ok Android","p-android.line":"Nálgast borð þitt úr síma, síðan sérstakt Android-forrit.","p-release.name":"Alfa ok lengra","p-release.line":"Lokat alfa, hin lifandi vefsíða, síðan beta.","p-languages.name":"Fleiri tungur","p-languages.line":"Meira en hundrað tungur, ok niðurdýfingarhátr fyrir þá er læra.","p-engines.name":"Fleiri gervigreindarvélar","p-engines.line":"Veldu Claude, Codex eða Gemini fyrir hvern erindreka.","p-pro.name":"Atvinnuháttr","p-pro.line":"Áhættumerki, sameiningarhlið, atvikaspjöld ok handrið.","p-self.name":"Gæta þín","p-self.line":"Þreytuhátr, sjálfsumönnunaráminningar ok 4:20.","p-servers.name":"Þjónar ok umfang","p-servers.line":"Almennar þjónastillingar, hlutverk ok áætlun fyrir vöxt.","p-livestream.name":"Streymisviðbætr","p-livestream.line":"Twitch-spjall, eigin tjáknmyndir ok opinbert beint yfirlit."},"words":{"button":"📖 Tækniorð","h":"📖 Tækniorð skýrð","intro":"Orðin er hugbúnaðarsmiðir (ok gervigreindarsveitir) nota, í einföldu máli.","search":"Leita orðs…","none":"Ekkert orð samsvarar því.","close":"Loka","list":[{"id":"backlog","word":"Backlog","text":"Hugmyndir ok starf sem eigi er enn áætlat. Ekkert þar er unnit unz þat flyzt í Til gerðar."},{"id":"sprint","word":"Sprint","text":"Stutt starfahrina (oft vika eða tvær) með ákveðnu safni spjalda til at ljúka.","also":["sprints"]},{"id":"standup","word":"Fundr","text":"Skjót yfirheyrsla: hvat hverr liðsmaðr gerði, hvat hann gerir næst, ok hvat tálmar honum.","also":["standup","stand-ups"]},{"id":"bug","word":"Bug","text":"Eitthvat er eigi starfar sem skyldi.","also":["bugs"]},{"id":"test","word":"Test","text":"At reyna lokit verk til at sjá at þat geri sem beðit var, áðr en þú samþykkir þat.","also":["tests"],"noTip":1},{"id":"commit","word":"Commit","text":"Vistuð ljósmynd kóðans, með stuttri athugasemd um hvat breyttisk. Þú getr ávallt snúit aftr til einnar.","also":["commits"]},{"id":"push","word":"Push","text":"At senda vistaðar ljósmyndir (commits) úr þessi tölvu upp til GitHub, svá at þær séu varðar ok deildar."},{"id":"branch","word":"Branch","text":"Sérstök starfslína í kóðanum, svá at breyta megi án at snerta aðalgerðina.","also":["branches"]},{"id":"merge","word":"Merge","text":"At sameina breytingar greinar aftr í aðalgerðina."},{"id":"repo","word":"Repo","text":"Mappa verksins með kóða ok allri sögu commits, oftast einnig geymd á GitHub.","also":["repository"]},{"id":"refactor","word":"Refactor","text":"At taka til í kóðanum án at breyta hvat hann gerir: smærri skrár, skýrari heiti, minni endrtekning."},{"id":"deploy","word":"Deploy","text":"At setja nýja gerð í gang, t.d. á þjón þar er menn nota hana."},{"id":"kanban","word":"Kanban","text":"Borð með dálkum (Til gerðar, Í verki, Lokit) þar er spjöld flytjask frá vinstri til hægri er starf gerisk."},{"id":"wip","word":"WIP-mark","text":"Work in progress: flest spjöld er dálkr skal geyma, svá at sveitin ljúki hlutum áðr en hún hefr fleiri.","also":["WIP"]},{"id":"pr","word":"Pull request","text":"Beiðni um at breytingar greinar séu skoðaðar ok sameinaðar í aðalgerðina.","also":["PR"]},{"id":"hook","word":"Hook","text":"Lítil skipun er rennr sjálf á ákveðnu augnabliki, t.d. þá er gervigreindarseta hefst, svá at sveitin heyri ummæli þín.","also":["hooks"]},{"id":"token","word":"Token","text":"Eining er notkun gervigreindar er talin í: nokkurn veginn fáir stafir lesnir eða ritaðir. Færri tákn, meira eftir af áætlun þinni.","also":["tokens"]},{"id":"agent","word":"Agent","text":"Gervigreind er starfar sjálf at verki: les kóðann, gerir breytingar, rennir athuganir ok segir frá.","also":["agents"]}]}};
